        lines: 6,
        guide: `<b>📖 정답 단서 (본문 1문단)</b><br>"청동기는 만들기 어렵고 귀해서 주로 <span class="wb-w-g-chip">무기</span>나 <span class="wb-w-g-chip">제사 도구</span>로 쓰였어요" / 대표 청동기: <span class="wb-w-g-chip">비파형 동검</span>·<span class="wb-w-g-chip">청동 거울</span> / "<span class="wb-w-g-chip">반달돌칼</span> 같은 농기구가 등장하면서 곡식 수확량이 크게 늘었어요"<br><br><b>✅ 예시 답안</b><br>청동기는 만들기 어렵고 귀해서 주로 <b>무기</b>(비파형 동검)와 <b>제사 도구</b>(청동 거울)로 쓰였어요. <b>반달돌칼</b>은 더 단단하고 정교한 농기구라서 곡식을 거두는 일이 쉬워졌고, 그 결과 <b>곡식 수확량이 크게 늘었어요</b>.<br><br><b>💡 지도 포인트</b><br>청동기는 귀해서 무기·제사용, 농기구는 여전히 돌이지만 더 정교해졌다는 두 줄기 흐름이 답에 들어가도록 안내해 주세요.`
