      '여러 나라가 자라나던 시기를 지나, 한반도와 만주에 큰 나라 세 곳이 단단히 자리 잡았어요. 우리는 이 시기를 <b>삼국 시대</b>라고 불러요. 만주와 한반도 북쪽에는 <b>고구려</b>가, 한반도 서남쪽에는 <b>백제</b>가, 동남쪽에는 <b>신라</b>가 있었지요. 이 세 나라는 모두 <b>부족 연합</b>으로 시작해서 점점 큰 나라로 자라났어요. 또한 한반도 남쪽 낙동강 부근에는 작은 여러 나라가 모인 <b>가야 연맹</b>도 함께 발전하고 있었어요. 삼국은 서로 영토를 넓히기 위해 경쟁하며 우리 역사에 큰 발자취를 남겼답니다.',
      '<b>고구려</b>는 부여에서 내려온 <b>주몽</b>이 기원전 37년에 세웠다고 전해져요. 산이 많은 지역이라 일찍부터 강한 군사력을 바탕으로 영토를 넓혀 갔지요. <b>백제</b>는 고구려에서 갈라져 나온 <b>온조</b>가 기원전 18년에 한강 가에 세운 나라예요. 백제는 넓은 평야와 한강이라는 좋은 교통로를 가졌기 때문에 농사도 잘되고 다른 나라와 무역도 활발했어요. 두 나라는 모두 시간이 흐르면서 작은 부족장들의 힘을 누르고 <b>왕</b>의 힘을 점점 키워 갔어요. 왕을 중심으로 나라의 모습이 갖춰지기 시작한 거예요.',
      '<b>신라</b>는 한반도 동남쪽 경주 부근에서 시작된 나라예요. 신화에 따르면 알에서 나온 <b>박혁거세</b>가 기원전 57년에 세웠다고 전해져요. 신라는 산으로 둘러싸여 다른 나라와의 교류가 늦었기 때문에 처음에는 발전이 느렸어요. 그래서 박씨·석씨·김씨 세 가문이 번갈아 가며 왕을 맡는 독특한 모습도 있었지요. 한편 낙동강 부근의 <b>가야 연맹</b>은 철이 많이 나는 자원을 바탕으로 일본과도 활발히 무역했어요. 하지만 가야는 하나의 큰 국가로 합치지 못해서 나중에는 신라에 흡수되었답니다.',
      '삼국은 점차 왕을 중심으로 강한 나라로 변해 갔어요. 이렇게 왕의 힘이 강해지는 과정을 <b>왕권 강화</b>라고 해요. 왕은 신하들에게 관직과 등급을 정해 주고, 새로운 법을 만들어 나라를 다스렸어요. 또 백성을 보호하고 농사를 돕기 위해 다양한 제도를 만들었지요. 삼국은 서로 영토와 백성을 두고 끊임없이 경쟁했어요. 어느 한 나라가 강해지면 다른 두 나라가 손을 잡고 막아서기도 했답니다. 이런 경쟁 속에서 각 나라는 더 발전했고, 우리 민족 문화의 다양한 뿌리가 만들어졌어요.'
