      '수나라의 거대한 군대가 고구려 깊숙이 밀고 들어왔을 때, 고구려에는 뛰어난 장군 <b>을지문덕</b>이 있었어요. 을지문덕은 거짓으로 후퇴하는 척하며 수의 군대를 깊이 끌어들였지요. 그러고는 청천강 부근의 <b>살수</b>에서 강물을 막아 두었다가 수의 군대가 강을 건너는 순간 한꺼번에 풀어 큰 승리를 거두었답니다. 이 전쟁을 <b>살수대첩</b>이라고 해요. 살수대첩에서 큰 피해를 입은 수나라는 결국 망하고 말았어요. 작은 지혜와 용기로 큰 적을 이긴 자랑스러운 우리 역사예요.',
