      '통일신라가 흔들리는 사이, 한반도에는 세 개의 나라가 다시 나타났어요. 이 시기를 <b>후삼국 시대</b>라고 해요. 옛 백제 지역에서는 <b>견훤</b>이 <b>후백제</b>를 세웠어요. 견훤은 강한 군사력으로 한반도 서남쪽을 다스렸지요. 옛 고구려 지역에서는 신라의 왕족 출신이라고 알려진 <b>궁예</b>가 <b>후고구려</b>를 세웠어요. 궁예는 처음에는 백성들의 마음을 모으며 큰 세력을 키웠지만, 점점 마음이 잔인해져 백성들의 신뢰를 잃고 말았답니다. 그래서 부하들이 새로운 왕을 모시기로 결심하게 되었지요.',
