      '고려가 세워졌지만 한반도는 여전히 후백제·고려·신라 세 나라로 나뉘어 있었어요. 왕건은 무엇보다 신라와 우호적인 관계를 맺으며 차근차근 힘을 키웠어요. 결국 935년에 신라가 스스로 고려에 항복했고, 936년에는 후백제까지 무너뜨려 <b>후삼국 통일</b>을 이루었답니다. 고려의 통일은 단순히 영토만 합친 것이 아니에요. 옛 신라·고구려·백제의 백성과 문화가 모두 한 나라 안에서 어우러진 진짜 통일이었지요. 고려는 그 뒤로도 약 500년 동안 우리 역사를 이끌어 가는 큰 나라가 되었어요.'
