      '고려가 자리 잡을 무렵 북쪽에서는 <b>거란</b>이 강력한 나라로 성장했어요. 거란은 송과 손잡은 고려를 압박하기 위해 세 차례나 큰 군대로 침입해 왔어요. 1차 침입 때 고려의 <b>서희</b>는 거란의 장군과 외교로 담판을 벌여 <b>강동 6주</b>라는 넓은 땅을 받아 냈답니다. 군대를 동원하지 않고 말솜씨로 큰 승리를 거둔 것이지요. 거란이 다시 침입했을 때는 <b>강감찬</b>이 <b>귀주대첩</b>에서 거란군을 크게 물리쳐 다시는 침공하지 못하게 만들었어요. 고려 사람들의 지혜와 용기가 빛난 사건이지요.',
