      '19세기에 들어 조선은 큰 변화의 물결을 마주하게 되었어요. 어린 임금 고종을 대신해 정치를 맡은 사람이 그의 아버지인 <b>흥선대원군</b>이에요. 흥선대원군은 무너진 왕권을 다시 세우기 위해 양반들에게도 군포를 내게 하고, 큰 권력을 가진 서원을 정리하는 등 과감한 개혁을 펼쳤지요. 한편 밖으로는 서양의 여러 나라가 우리나라와 통상하자고 거듭 찾아왔어요. 흥선대원군은 서양과의 교류를 거부하고 <b>통상 수교 거부</b> 정책을 펼쳤답니다. 전국에 <b>척화비</b>를 세워 서양과 손잡지 말 것을 강하게 다짐했지요.',
