      '나라가 개항하자 조선 안에서는 새로운 흐름이 생기기 시작했어요. 한쪽에서는 서양의 문물과 제도를 받아들여 나라를 발전시키자는 의견이 나왔지요. 이런 사람들을 <b>개화파</b>라고 해요. 김옥균·박영효 같은 사람들은 서양의 정치 제도와 기술을 적극적으로 배워야 한다고 주장했어요. 반면 우리 전통과 유교의 가르침을 지키며 서양 문물을 막아야 한다고 주장한 사람들도 있었답니다. 이들을 <b>위정척사파</b>라고 해요. 위정척사파는 서양 사상을 받아들이면 우리의 정체성이 흔들린다고 걱정했어요.',
